public record BookingReceipt(
        String title,
        long reservationId,
        String guestName,
        String passportNumber,
        String country,
        int roomNumber,
        RoomType roomType,
        LocalDate checkIn,
        LocalDate checkOut,
        int nights,
        BigDecimal subtotal,
        BigDecimal discount,
        BigDecimal total) implements ReservationDocument {

