private static NewReservation readNewReservation(Context ctx) {
    CreateReservationRequest body;
    try {
        body = ctx.bodyAsClass(CreateReservationRequest.class);
    } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
        throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
    }
    if (body == null
            || body.roomNumber() == null
            || isBlank(body.guestName())
            || isBlank(body.guestEmail())
            || body.checkIn() == null
            || body.checkOut() == null
            || body.guests() == null
            || body.ratePlan() == null) {
        throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
    }
    Guest guest = createGuest(body);
    return new NewReservation(
            body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
}

private static Guest createGuest(CreateReservationRequest body) {
    boolean hasCpf = !isBlank(body.guestCpf());
    boolean hasCorporate = !isBlank(body.companyCnpj()) && !isBlank(body.companyName());
    boolean hasPassport = !isBlank(body.guestPassport()) && !isBlank(body.guestCountry());

    int identificationCount = (hasCpf ? 1 : 0) + (hasCorporate ? 1 : 0) + (hasPassport ? 1 : 0);
    if (identificationCount != 1) {
        throw new HotelException(
                ErrorCode.INVALID_REQUEST,
                "exactly one guest identification is required: guestCpf, or (companyCnpj and companyName), or (guestPassport and guestCountry)");
    }

    if (hasCpf) {
        return new hotel.reservations.IndividualGuest(body.guestName(), body.guestEmail(), body.guestCpf());
    }
    if (hasCorporate) {
        return new hotel.reservations.CorporateGuest(
                body.guestName(), body.guestEmail(), body.companyCnpj(), body.companyName());
    }
    return new hotel.reservations.ForeignGuest(
            body.guestName(), body.guestEmail(), body.guestPassport(), body.guestCountry());
}

